mapper.select:
select audit_id, event_key, source, action, object_type, object_id, object_name,
       before_value, after_value, reason, related_object, operator, audit_time
from sys_business_audit

    and source = #{source}
    and action = #{action}
    and object_type = #{objectType}
    and object_id = #{objectId}
    and operator like concat('%', #{operator}, '%')
    and audit_time >= #{params.beginTime}
    and audit_time <= #{params.endTime}

order by audit_time desc, audit_id desc
